CREATE TYPE "Role" AS ENUM ('RIDER','DRIVER','ADMIN');
CREATE TYPE "RideStatus" AS ENUM ('REQUESTED','SEARCHING','ACCEPTED','ARRIVING','ARRIVED','IN_PROGRESS','COMPLETED','CANCELLED','EXPIRED');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','SUCCEEDED','FAILED','REFUNDED');
CREATE TABLE "User" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "phone" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'RIDER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DriverProfile" ("userId" UUID NOT NULL, "vehicleMake" TEXT, "vehicleModel" TEXT, "plate" TEXT, "verified" BOOLEAN NOT NULL DEFAULT false, "online" BOOLEAN NOT NULL DEFAULT false, "lat" DOUBLE PRECISION, "lng" DOUBLE PRECISION, "locationUpdatedAt" TIMESTAMP(3), CONSTRAINT "DriverProfile_pkey" PRIMARY KEY ("userId"));
CREATE TABLE "RefreshToken" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RefreshToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Ride" ("id" UUID NOT NULL, "riderId" UUID NOT NULL, "driverId" UUID, "status" "RideStatus" NOT NULL DEFAULT 'REQUESTED', "pickupLat" DOUBLE PRECISION NOT NULL, "pickupLng" DOUBLE PRECISION NOT NULL, "dropoffLat" DOUBLE PRECISION NOT NULL, "dropoffLng" DOUBLE PRECISION NOT NULL, "distanceKm" DOUBLE PRECISION NOT NULL, "durationMin" DOUBLE PRECISION NOT NULL, "surge" DOUBLE PRECISION NOT NULL DEFAULT 1, "fare" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'IRR', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "completedAt" TIMESTAMP(3), CONSTRAINT "Ride_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RideEvent" ("id" UUID NOT NULL, "rideId" UUID NOT NULL, "actorId" UUID, "fromStatus" "RideStatus", "toStatus" "RideStatus" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RideEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Payment" ("id" UUID NOT NULL, "rideId" UUID NOT NULL, "amount" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'IRR', "status" "PaymentStatus" NOT NULL DEFAULT 'PENDING', "provider" TEXT NOT NULL DEFAULT 'mock', "providerReference" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Payment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Rating" ("id" UUID NOT NULL, "rideId" UUID NOT NULL, "fromUserId" UUID NOT NULL, "toUserId" UUID NOT NULL, "score" INTEGER NOT NULL, "comment" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Rating_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_phone_key" ON "User"("phone");
CREATE UNIQUE INDEX "RefreshToken_tokenHash_key" ON "RefreshToken"("tokenHash");
CREATE INDEX "RefreshToken_userId_idx" ON "RefreshToken"("userId");
CREATE INDEX "Ride_status_createdAt_idx" ON "Ride"("status","createdAt");
CREATE INDEX "Ride_riderId_createdAt_idx" ON "Ride"("riderId","createdAt");
CREATE INDEX "Ride_driverId_status_idx" ON "Ride"("driverId","status");
CREATE INDEX "RideEvent_rideId_createdAt_idx" ON "RideEvent"("rideId","createdAt");
CREATE UNIQUE INDEX "Payment_rideId_key" ON "Payment"("rideId");
CREATE UNIQUE INDEX "Payment_providerReference_key" ON "Payment"("providerReference");
CREATE UNIQUE INDEX "Rating_rideId_key" ON "Rating"("rideId");
ALTER TABLE "DriverProfile" ADD CONSTRAINT "DriverProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Ride" ADD CONSTRAINT "Ride_riderId_fkey" FOREIGN KEY ("riderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Ride" ADD CONSTRAINT "Ride_driverId_fkey" FOREIGN KEY ("driverId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "RideEvent" ADD CONSTRAINT "RideEvent_rideId_fkey" FOREIGN KEY ("rideId") REFERENCES "Ride"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_rideId_fkey" FOREIGN KEY ("rideId") REFERENCES "Ride"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Rating" ADD CONSTRAINT "Rating_rideId_fkey" FOREIGN KEY ("rideId") REFERENCES "Ride"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Rating" ADD CONSTRAINT "Rating_fromUserId_fkey" FOREIGN KEY ("fromUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Rating" ADD CONSTRAINT "Rating_toUserId_fkey" FOREIGN KEY ("toUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
-- One active ride per driver, enforced at database level.
CREATE UNIQUE INDEX "Ride_one_active_driver" ON "Ride"("driverId") WHERE "driverId" IS NOT NULL AND "status" IN ('ACCEPTED','ARRIVING','ARRIVED','IN_PROGRESS');
